efix):])\\n+    else:\\n+        para.add_run(text)\\n+    return para\\n+\\n+\\n+def bullet(text, level=0):\\n+    para = doc.add_paragraph(style=\\\"List Bullet\\\" if level == 0 else \\\"List Bullet 2\\\")\\n+    para.add_run(text)\\n+    return para\\n+\\n+\\n+def number(text):\\n+    para = doc.add_paragraph(style=\\\"List Number\\\")\\n+    para.add_run(text)\\n+    return para\\n+\\n+\\n+def table(headers, rows, widths=None):\\n+    t = doc.add_table(rows=1, cols=len(headers))\\n+    t.style = \\\"Table Grid\\\"\\n+    t.alignment = WD_TABLE_ALIGNMENT.CENTER\\n+    t.autofit = False\\n+    hdr = t.rows[0]\\n+    set_repeat_table_header(hdr)\\n+    for i, h in enumerate(headers):\\n+        c = hdr.cells[i]\\n+        c.text = h\\n+        set_cell_shading(c, \\\"D9EAF7\\\")\\n+        c.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER\\n+        if widths:\\n+            c.width = Cm(widths[i])\\n+        for r in c.paragraphs[0].runs:\\n+            r.bold = True\\n+            r.font.size = Pt(9)\\n+    for row in rows:\\n+        cells = t.add_row().cells\\n+        for i, value in enumerate(row):\\n+            cells[i].text = value\\n+            cells[i].vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.TOP\\n+            set_cell_margins(cells[i])\\n+            if widths:\\n+                cells[i].width = Cm(widths[i])\\n+            for para in cells[i].paragraphs:\\n+                para.paragraph_format.space_after = Pt(2)\\n+                para.paragraph_format.line_spacing = 1.05\\n+                for run in para.runs:\\n+                    run.font.size = Pt(8.8)\\n+    doc.add_paragraph().paragraph_format.space_after = Pt(0)\\n+    return t\\n+\\n+\\n+title = doc.add_paragraph(style=\\\"Title\\\")\\n+title.alignment = WD_ALIGN_PARAGRAPH.CENTER\\n+title.add_run(\\\"内分泌专科入院评估\\\")\\n+subtitle = doc.add_paragraph()\\n+subtitle.alignment = WD_ALIGN_PARAGRAPH.CENTER\\n+r = subtitle.add_run(\\\"育龄女性｜高血糖危象排查、多饮多尿与马凡样表型分阶段路径\\\")\\n+r.font.size = Pt(11)\\n+r.font.color.rgb = RGBColor(80, 80, 80)\\n+\\n+alert = doc.add_table(rows=1, cols=1)\\n+alert.style = \\\"Table Grid\\\"\\n+cell = alert.cell(0, 0)\\n+set_cell_shading(cell, \\\"FFF2CC\\\")\\n+cell.text = (\\n+    \\\"安全结论：本次入院当前血气、血 β-羟丁酸、电解质、血浆渗透压和定量尿量均未见回报。\\\"\\n+    \\\"在这些结果返回前，只能下“高血糖危象待排（DKA/HHS/重叠）”；不得据外院尿酮“+”或无消化道症状认定无酸中毒，\\\"\\n+    \\\"亦不得先行禁水、限水或高渗刺激试验。\\\"\\n+)\\n+for rr in cell.paragraphs[0].runs:\\n+    rr.bold = True\\n+    rr.font.size = Pt(10)\\n+\\n+p(\\\"评估依据与当前事实\\\", \\\"Heading 1\\\")\\n+p(\\n+    \\\"本评估仅以给定本地材料作为患者事实来源。外院检验为人工转录：一月余前曾记录空腹血糖 21.7 mmol/L、\\\"\\n+    \\\"餐后 2 小时血糖 30.6 mmol/L、HbA1c 14.6%、尿糖 4+、尿酮 +；三日前门诊记录“糖尿病”并开具诺和佳 10 U、每日 2 次，\\\"\\n+    \\\"用药后无血糖监测。上述结果仅提示近期风险，不能替代本次当前样本。\\\"\\n+)\\n+p(\\n+    \\\"患者诉约 3 年多饮、主观多尿，饮水约 4–5 L/d，但从未记录 24 h 尿量；近 1 月体重下降 5 kg。\\\"\\n+    \\\"本次查体 T 36.7℃、P 98/min、R 16/min、BP 116/69 mmHg，身高 166 cm、体重 76.7 kg、BMI 27.8 kg/m²、腰围 106 cm。\\\"\\n+    \\\"既往有桥本甲状腺炎/亚临床甲减、甲状腺结节、脂肪肝、晶状体脱位及卵巢囊肿病史；拇指征、腕征阳性，手指细长并有可疑脊柱侧弯等马凡样线索。\\\"\\n+)\\n+\\n+p(\\\"当前诊断层级（结果未回报时）\\\", \\\"Heading 2\\\")\\n+table(\\n+    [\\\"层级\\\", \\\"目前可写\\\", \\\"边界\\\"],\\n+    [\\n+        (\\\"已记录/可确认的临床问题\\\", \\\"糖尿病（门诊已诊断，分型待定）；多年多饮、主观多尿；近期体重下降；晶状体脱位病史伴马凡样体征；桥本甲状腺炎/亚临床甲减及甲状腺结节病史。\\\", \\\"门诊诊断可保留，但本次血糖控制状态、类型和急性并发症仍需当前样本。\\\"),\\n+        (\\\"当前必须排除\\\", \\\"高血糖危象：DKA、HHS及二者重叠；脱水/急性肾损伤；钠、钾、镁、磷异常；感染、妊娠、胰腺炎、心脑血管事件或用药/治疗中断等诱因。\\\", \\\"均为“待排”，不能写成阴性或确诊。可交流、无恶心呕吐腹痛不具有排除力。\\\"),\\n+        (\\\"后续待证实\\\", \\\"持续渗透性利尿或低渗多尿；AVP 缺乏、肾性尿崩症、原发性烦渴；糖尿病慢性并发症；马凡综合征或相关遗传病；月经紊乱/PCOS 等。\\\", \\\"未量到 24 h 尿量前不能诊断多尿；无主动脉/眼科/遗传证据不能诊断马凡综合征。\\\"),\\n+    ],\\n+    [3.1, 8.5, 5.5],\\n+)\\n+\\n+p(\\\"一、当前急症排查\\\", \\\"Heading 1\\\")\\n+p(\\\"1. 立即完成：取当前样本并同步床旁评估\\\", \\\"Heading 2\\\")\\n+table(\\n+    [\\\"优先级\\\", \\\"检查/观察\\\", \\\"目的与解释\\\"],\\n+    [\\n+        (\\\"立即床旁\\\", \\\"复测生命体征、意识/GCS、呼吸型态、黏膜/皮肤、毛细血管再充盈、颈静脉、外周灌注；卧立位血压/心率（安全可行时）；床旁指尖血糖；建立严格出入量并测体重。\\\", \\\"识别低灌注、容量不足、神经功能异常及尿量变化。一次正常血压或可交流不能排除危象。\\\"),\\n+        (\\\"立即送检\\\", \\\"静脉血糖；血 β-羟丁酸（优先于单纯尿酮）；静脉血气 pH、HCO₃⁻；Na、K、Cl、总 CO₂/HCO₃⁻、尿素、肌酐、eGFR、Mg、磷；实测血浆渗透压。\\\", \\\"同时计算阴离子间隙；按 mmol/L 计算有效渗透压 2×Na+glucose，并可估算总渗透压 2×Na+glucose+urea；报告实测钠及按高血糖校正钠。静脉血气通常足以筛查酸碱，低氧/呼吸适应证时再行动脉血气。\\\"),\\n+        (\\\"同批基础\\\", \\\"尿常规及尿沉渣（当前尿糖、尿酮、比重）；CBC；肝功能；当前尿/血 hCG（育龄且妊娠状态未核实）。可留取配对点尿渗透压/尿 Na、K，但不得因此延误危象处理。\\\", \\\"尿酮受方法和时相影响，不能代替 β-羟丁酸。急性高血糖期的尿渗透压可由葡萄糖升高，不能直接用于诊断尿崩症。\\\"),\\n+        (\\\"结果触发\\\", \\\"明显 K 异常、心悸或危象时 12 导联 ECG/心电监护；低灌注或不明酸中毒时乳酸；必要时重复血糖、电解质、肌酐、磷、β-羟丁酸和静脉 pH。\\\", \\\"若确认危象，按实时结果进入监护、补液、胰岛素和钾管理流程；本文不在无结果时预设固定处方。\\\"),\\n+    ],\\n+    [2.3, 8.6, 6.2],\\n+)\\n+\\n+p(\\\"2. 结果返回后的危象判定框架\\\", \\\"Heading 2\\\")\\n+table(\\n+    [\\\"诊断\\\", \\\"公开标准的组成条件\\\", \\\"本例当前状态\\\"],\\n+    [\\n+        (\\\"DKA\\\", \\\"须同时具备：糖尿病/高血糖（血糖 ≥11.1 mmol/L 或既往糖尿病）、酮症（β-羟丁酸 ≥3.0 mmol/L，或尿酮 ≥2+）及代谢性酸中毒（pH <7.3 和/或 HCO₃⁻ <18 mmol/L）。阴离子间隙可辅助，但不能替代三要素。\\\", \\\"仅有外院一月余前尿酮 + 和高血糖转录；本次血酮、pH、HCO₃⁻均待查，故只能写 DKA 待排。\\\"),\\n+        (\\\"HHS\\\", \\\"显著高血糖（通常 ≥33.3 mmol/L）+ 高渗（有效渗透压 >300 mOsm/kg 或总渗透压 >320 mOsm/kg）+ 无显著酮症（β-羟丁酸 <3.0 mmol/L/尿酮 <2+）+ 无显著酸中毒（pH ≥7.3 且 HCO₃⁻ ≥15 mmol/L）。\\\", \\\"本次血糖、实测/计算渗透压、血酮及酸碱均待查，故只能写 HHS 待排。\\\"),\\n+        (\\\"DKA/HHS 重叠\\\", \\\"若同时出现显著高渗及 DKA 的酮症/酸中毒特征，按重叠型识别并提高监护级别。\\\", \\\"不能先验二选一。\\\"),\\n+    ],\\n+    [2.4, 10.4, 4.3],\\n+)\\n+p(\\\"注：若实验室采用不同参考范围或危象方案，以本院经审核方法学为准；以上阈值只用于解释待回报结果。\\\")\\n+\\n+p(\\\"3. 脱水、电解质紊乱与诱因：并行但不延误\\\", \\\"Heading 2\\\")\\n+bullet(\\\"容量/肾功能：把查体、严格出入量、体重、尿素/肌酐、钠及渗透压合并判断；高血糖可造成移位性低钠，必须同时看实测钠、校正钠和变化趋势。\\\")\\n+bullet(\\\"电解质：即使血钾正常或偏高也可能存在总体钾缺失；在获得 K 和肾功能前不得盲目推进胰岛素/补钾。Mg、磷异常按症状、程度和危象流程处理。\\\")\\n+bullet(\\\"病史核查：最后一次诺和佳给药时间/剂量、漏用或错误用药、进食和饮水、近期糖皮质激素/噻嗪/锂盐/SGLT2 抑制剂等；材料只证明处方，不证明实际规律使用。\\\")\\n+bullet(\\\"感染：复核发热、呼吸道、泌尿道、皮肤/牙源症状并查体；CBC/尿检作为基础。仅在发热、局灶征象、脓毒症或影像指征时做血/尿培养、CRP/PCT、胸片等，不因高血糖常规无差别全做。\\\")\\n+bullet(\\\"其他按适应证：腹痛/呕吐或胰腺炎线索查脂肪酶；胸痛/缺血线索查肌钙蛋白和 ECG；局灶神经征象按卒中路径；药物/毒物、手术应激等依病史。育龄患者同步 hCG；必要急救影像不因等待妊娠结果而不当延误。\\\")\\n+\\n+p(\\\"二、病情稳定后\\\", \\\"Heading 1\\\")\\n+p(\\\"进入条件：DKA/HHS 已排除或纠正，循环和电解质稳定、血糖不再造成显著渗透性干扰，可安全进食饮水；若条件未满足，本节检查应延后或仅留样不解释。\\\", bold_prefix=\\\"进入条件：\\\")\\n+\\n+p(\\\"1. 糖尿病分型\\\", \\\"Heading 2\\\")\\n+table(\\n+    [\\\"步骤\\\", \\\"检查\\\", \\\"结论边界\\\"],\\n+    [\\n+        (\\\"确认病程/控制\\\", \\\"本次静脉血糖、HbA1c；CBC并关注贫血/输血/血红蛋白病、肾病等对 HbA1c 的影响，必要时选果糖胺/糖化白蛋白。\\\", \\\"既往转录 HbA1c 14.6% 只能描述一月余前；三日胰岛素通常不代表长期控制已改善。\\\"),\\n+        (\\\"自身免疫证据\\\", \\\"GAD65 抗体优先，联合 IA-2、ZnT8；必要时胰岛细胞抗体。胰岛素自身抗体在已使用外源胰岛素后解释受限，应标明采血相对用药时点。\\\", \\\"阳性支持自身免疫性 1 型；阴性不能单独排除，尤其抗体谱不全或病程较久。\\\"),\\n+        (\\\"β 细胞储备\\\", \\\"酮症/糖毒性纠正后，测空腹或刺激 C 肽并同步血糖、肌酐；若在急性期偏低，稳定后复测。\\\", \\\"C 肽必须结合当时血糖和肾功能；急性糖毒性可造成暂时抑制。\\\"),\\n+        (\\\"综合归类\\\", \\\"结合发病年龄、体型/代谢表型、酮症倾向、抗体、C 肽、家族史及药物史，鉴别自身免疫 1 型、2 型、酮症倾向糖尿病及继发性糖尿病。\\\", \\\"BMI 27.8 kg/m²和腰围 106 cm支持胰岛素抵抗线索，但不排除 1 型。外院尿酮 + 也不能单独定义酮症倾向亚型。\\\"),\\n+        (\\\"遗传/继发按适应证\\\", \\\"若年轻起病、连续多代常染色体显性家族史、抗体阴性且 C 肽保留，考虑单基因糖尿病基因检测；有胰腺病、血色病、库欣/肢端肥大等表型再做定向检查。\\\", \\\"本材料只有两位外祖辈患糖尿病，尚不足以直接启动或确诊 MODY；不做无表型的广泛内分泌筛查。\\\"),\\n+    ],\\n+    [2.6, 9.0, 5.5],\\n+)\\n+\\n+p(\\\"2. 并发症与心代谢风险：常规基础 vs 有适应证检查\\\", \\\"Heading 2\\\")\\n+table(\\n+    [\\\"类型\\\", \\\"稳定后常规基础评估\\\", \\\"仅有适应证才做\\\"],\\n+    [\\n+        (\\\"床旁/查体\\\", \\\"血压、体重/BMI、腰围；皮肤和胰岛素注射部位；双足皮肤/畸形/溃疡、足背/胫后动脉；10 g 单丝联合至少一种感觉检查（128 Hz 音叉/针刺/踝反射）；询问低血糖及自主神经症状。\\\", \\\"ABI：脉搏减弱、跛行、足病高风险等；神经传导：表现不典型、明显不对称、运动受累或诊断不清；胃排空/自主神经专项：有相应症状。\\\"),\\n+        (\\\"肾脏\\\", \\\"血肌酐/eGFR；稳定后晨尿 UACR。\\\", \\\"UACR 异常需在排除月经、感染、剧烈运动、急性高血糖等干扰后，于 3–6 月内重复确认；超声/肾科评估用于非典型尿沉渣、快速 eGFR 下降等。\\\"),\\n+        (\\\"眼部\\\", \\\"安排散瞳眼底检查/眼底照相评估糖尿病视网膜病变；本例另需眼科裂隙灯确认晶状体脱位。\\\", \\\"OCT、荧光造影等由眼科在视力下降、黄斑病变或治疗规划时决定，不作无差别常规。\\\"),\\n+        (\\\"心血管/代谢\\\", \\\"空腹血脂；肝功能；复核吸烟、睡眠呼吸暂停线索、血压和家族早发心血管史；营养和运动评估。\\\", \\\"静息 ECG/肌钙蛋白、负荷试验、冠脉影像仅按症状、心电异常或总体风险适应证；肝脏影像/纤维化评估按持续转氨酶异常和脂肪肝风险分层。\\\"),\\n+        (\\\"其他相关\\\", \\\"口腔、皮肤感染风险及疫苗史；提供低血糖处理、病日规则、血糖/酮体监测和避孕/孕前咨询。\\\", \\\"无症状患者不常规做全身影像或肿瘤标志物。\\\"),\\n+    ],\\n+    [2.4, 9.2, 5.5],\\n+)\\n+\\n+p(\\\"3. 甲状腺与生殖代谢\\\", \\\"Heading 2\\\")\\n+table(\\n+    [\\\"领域\\\", \\\"基础评估\\\", \\\"按指征追加/解释限制\\\"],\\n+    [\\n+        (\\\"甲状腺功能\\\", \\\"病情稳定后查 TSH、FT4；核对既往报告、药物及服药方法。\\\", \\\"急性危重病可出现非甲状腺疾病改变，轻度异常稳定后复核；TPOAb/TgAb若既往已明确桥本通常无需反复定量。FT3仅在特定甲亢/转换异常情境使用。\\\"),\\n+        (\\\"甲状腺结节\\\", \\\"颈部查体，调取既往超声；按本院超声风险分层决定复查间隔。\\\", \\\"FNA由结节大小、超声高危征象和淋巴结决定；不因“有结节史”自动穿刺。核素扫描仅在 TSH 受抑等适应证下，并受妊娠/哺乳限制。\\\"),\\n+        (\\\"妊娠与月经\\\", \\\"先问当前末次月经、避孕、性生活和妊娠可能，查 hCG；记录材料中的 2022-09-25 仅为旧病历值。待代谢稳定后整理周期、异常子宫出血、泌乳及高雄表现。\\\", \\\"妊娠试验阳性立即转入孕期糖尿病/甲状腺管理；严重高血糖、体重变化和急性应激本身可扰乱月经。\\\"),\\n+        (\\\"月经稀发/PCOS 路径\\\", \\\"排妊娠后，根据表现查 TSH、泌乳素；有高雄证据时查总睾酮（可靠方法）±SHBG/游离雄激素指数，必要时 DHEAS。\\\", \\\"疑非经典 CAH时晨间 17-OHP；快速男性化/雄激素显著升高时评估肿瘤；库欣表型才筛查皮质醇。PCOS须满足规范诊断组合并排除其他病因，不能仅凭月经不规律或卵巢囊肿病史确诊。盆腔超声按妇科症状、囊肿随访或诊断需要。\\\"),\\n+    ],\\n+    [2.5, 8.5, 6.1],\\n+)\\n+\\n+p(\\\"4. 多年多饮多尿：三阶段鉴别路径\\\", \\\"Heading 2\\\")\\n+table(\\n+    [\\\"阶段\\\", \\\"先做什么\\\", \\\"触发下一步的条件/结论\\\"],\\n+    [\\n+        (\\\"A. 急性高血糖期：先考虑溶质性/渗透性利尿\\\", \\\"当前血糖、尿糖、Na/K/Ca、尿素/肌酐、实测血浆及尿渗透压；严格出入量。查看 SGLT2 抑制剂、利尿剂、甘露醇、高蛋白/高盐负荷等。\\\", \\\"血糖显著升高并糖尿、尿渗透压偏高时，渗透性利尿优先。先纠正高血糖和容量/电解质；此时不做禁水或高渗刺激。\\\"),\\n+        (\\\"B. 稳定后确认是否真性多尿、是否低渗\\\", \\\"连续严格 24 h 尿量（必要时重复），同步饮水量；配对血 Na、血浆渗透压、尿渗透压/比重、尿 Na/K/尿素/葡萄糖；排除未控制糖尿、低钾、高钙、肾功能异常及药物。\\\", \\\"成人尿量 >3 L/d 或 >50 mL/kg/d 可作客观多尿标准；按本例 76.7 kg 后者约 3.84 L/d，这只是阈值而非已测尿量。尿渗透压 <300 mOsm/kg且持续多尿，才称低渗多尿并进入 C；>800 通常反对 AVP 轴障碍；300–800 为灰区，先看溶质排泄和临床背景。\\\"),\\n+        (\\\"C. 低渗多尿分型\\\", \\\"先用配对 Na/血浆渗透压判断：高钠/高渗更支持 AVP 缺乏或肾性抵抗；低正常钠/低渗更偏原发性烦渴，但均非单项确诊。由内分泌专科选择受控禁水-去氨加压素试验，或条件允许时高渗盐水刺激 copeptin；同时据病史做定向病因学。\\\", \\\"去氨加压素后尿浓缩明显更支持中枢性 AVP 缺乏，反应小更支持肾性抵抗；部分型和长期原发性烦渴可重叠，需完整曲线/copeptin解释。确立中枢性 AVP 缺乏后才做垂体 MRI及垂体激素；肾性路径复核锂盐、低钾、高钙、肾病及遗传线索；原发性烦渴需药物/精神行为评估并避免武断归因。\\\"),\\n+    ],\\n+    [2.5, 8.8, 5.8],\\n+)\\n+\\n+p(\\\"动态试验的硬性安全前提\\\", \\\"Heading 3\\\")\\n+bullet(\\\"仅在 DKA/HHS 已排除或纠正、显著高血糖及糖尿性渗透利尿已控制、患者血流动力学稳定且基本等容后执行。\\\")\\n+bullet(\\\"先确认持续低渗多尿，并复核 Na、K、Ca、肾功能及基础血浆/尿渗透压；显著高钠或低钠、低钾、高钙、脱水、肾功能不稳或无法配合者先纠正/评估，不得直接试验。\\\")\\n+bullet(\\\"须内分泌专科书面方案和具备经验的监护环境，精确记录体重、尿量、尿渗透压、血钠/血浆渗透压、生命体征和症状；高渗盐水刺激需连续钠监测和及时纠偏能力。不得仅凭交班摘要放行。\\\")\\n+bullet(\\\"受控禁水预设停止条件：体重下降约 3%–5%、出现低血压/体位性不适或明显心动过速、不能耐受的口渴/神经症状、血钠达到本院安全上限（常以 ≥150 mmol/L）或血浆渗透压达到方案上限（常以 ≥300 mOsm/kg），以及监护医师认为有风险的任何情况。达到停止条件后按方案复水/处理。\\\")\\n+bullet(\\\"若基础已高钠且尿液稀释，可能无需再以禁水增加风险；优先由专科结合 copeptin/病因学选择更安全的确认方式。妊娠、癫痫、心肾疾病等特殊情况需个体化，必要时不做动态试验。\\\")\\n+\\n+p(\\\"三、后续专科评估\\\", \\\"Heading 1\\\")\\n+p(\\\"1. 马凡综合征/马凡样综合征\\\", \\\"Heading 2\\\")\\n+table(\\n+    [\\\"模块\\\", \\\"计划\\\", \\\"本例边界\\\"],\\n+    [\\n+        (\\\"眼科确认\\\", \\\"眼科裂隙灯确认是否为晶状体异位/脱位、方向与双侧性；记录屈光、眼轴、视网膜及青光眼风险。\\\", \\\"材料只有“晶状体脱位 1 年”病史，尚无眼科原始报告，不能直接作为修订 Ghent 的已确认主标准。\\\"),\\n+        (\\\"心血管首选\\\", \\\"稳定后尽快经胸超声心动图：主动脉环/窦部/窦管交界/升主动脉标准化测量并按年龄体表面积计算 Z 值，同时评估主动脉瓣返流、二尖瓣脱垂及心功能。询问胸背痛、晕厥、心悸和家族主动脉事件。\\\", \\\"无主动脉根数据，不能满足以主动脉病变为核心的确诊组合。若出现突发胸背痛、脉搏/血压不对称、神经缺损或新发主动脉返流，按急性主动脉综合征急诊处理。\\\"),\\n+        (\\\"系统评分\\\", \\\"由临床遗传/心血管专科规范复查：腕征+拇指征、胸廓、后足、扁平足、脊柱侧弯、肘伸展、面容、皮纹、近视、气胸、硬膜扩张、髋臼突出、二尖瓣脱垂等；补三代家系。\\\", \\\"本例腕征与拇指征均阳性可作为系统评分线索；可疑侧弯需确认。臂展/身高=171/166≈1.03、上/下部量=80/86≈0.93，应按适用人群阈值判断，不能自动计分。手指细长、关节活动度大、拇外翻也不能自行另加 Ghent 分。\\\"),\\n+        (\\\"遗传\\\", \\\"遗传咨询后行 FBN1 检测；表型重叠或 FBN1 阴性且临床仍高度怀疑时选遗传性胸主动脉病/结缔组织病 panel，并做变异分级和家系验证。\\\", \\\"意义未明变异不能单独确诊；阴性结果亦不能取代临床随访。\\\"),\\n+        (\\\"全主动脉\\\", \\\"超声不能完整显示或达到诊断/基线适应证时，评估全主动脉。非急诊优先 MRI（按妊娠和对比剂风险决定是否增强）；CT血管成像用于 MRI 不可行、需更高空间分辨率或急症。\\\", \\\"非急诊电离辐射检查必须先核实妊娠；不得把拟行影像写成已完成。\\\"),\\n+    ],\\n+    [2.5, 9.2, 5.4],\\n+)\\n+\\n+p(\\\"修订 Ghent 的结论方式\\\", \\\"Heading 3\\\")\\n+p(\\n+    \\\"无明确家族史时，典型确诊组合通常以主动脉根扩张/夹层为核心，结合已确认晶状体异位、致病性 FBN1 变异或系统评分；\\\"\\n+    \\\"也可由晶状体异位与已知可导致主动脉病的 FBN1 变异组成特定组合。必须逐项满足规则并排除替代诊断。\\\"\\n+    \\\"本例目前只能写“晶状体脱位病史伴马凡样体征，马凡综合征待评估”，不能凭体型或腕/拇指征直接确诊。\\\"\\n+)\\n+\\n+p(\\\"2. 相关鉴别（由表型触发）\\\", \\\"Heading 2\\\")\\n+table(\\n+    [\\\"鉴别\\\", \\\"重点线索\\\", \\\"定向检查\\\"],\\n+    [\\n+        (\\\"同型半胱氨酸尿症（CBS相关）\\\", \\\"晶状体异位、马凡样骨骼表型，合并血栓、发育/认知或骨质线索；晶状体移位方向由眼科记录。\\\", \\\"空腹血浆总同型半胱氨酸、蛋氨酸，并转遗传代谢专科；异常后酶学/基因确认。\\\"),\\n+        (\\\"Loeys–Dietz 谱系\\\", \\\"动脉瘤/迂曲，眼距宽、双裂悬雍垂/腭裂、颈椎或足部异常等；主动脉风险可不完全由根部尺寸体现。\\\", \\\"全动脉树影像的范围由心血管/遗传专科决定；TGFBR1/2、SMAD2/3、TGFB2/3、SKI等相关 panel。\\\"),\\n+        (\\\"血管型 EDS\\\", \\\"易瘀伤、半透明皮肤、特征面容、动脉/肠/子宫脆性，关节表现常以小关节为主。\\\", \\\"临床遗传评估与 COL3A1 检测；避免仅凭“关节松”归类。\\\"),\\n+        (\\\"先天性挛缩性蜘蛛指（FBN2）\\\", \\\"蜘蛛指、挛缩、耳廓皱褶、肌发育不足/脊柱后侧凸。\\\", \\\"针对性 FBN2 或 panel。\\\"),\\n+        (\\\"MASS表型/二尖瓣脱垂综合征及其他\\\", \\\"近视、二尖瓣、皮肤/骨骼表现而无进行性主动脉根病变；亦需考虑 Shprintzen–Goldberg 等表型。\\\", \\\"长期主动脉随访和遗传评估；诊断需随时间验证，不能在首次无主动脉异常时仓促封闭。\\\"),\\n+    ],\\n+    [3.0, 8.4, 5.7],\\n+)\\n+\\n+p(\\\"3. 妊娠核实与非急诊电离辐射影像安全\\\", \\\"Heading 2\\\")\\n+number(\\\"材料中的末次月经 2022-09-25 仅是既往记录，不能证明当前未妊娠。每次非急诊含电离辐射的腹盆部/主动脉影像前，重新询问并记录当前末次月经、周期、避孕、性生活及妊娠可能，按本院时间窗完成尿或血 hCG。\\\")\\n+number(\\\"若 hCG 阳性、结果不确定或妊娠可能不能排除：先判断检查能否延期或改用超声/MRI（通常优先不使用钆对比剂）；与影像科、产科共同进行母胎风险—获益评估并记录知情沟通。核素检查同样须核实妊娠/哺乳。\\\")\\n+number(\\\"若怀疑急性主动脉综合征或其他危及生命情况，必要影像不得因妊娠核实流程造成不当延误；选择能最快回答临床问题且剂量优化的方案，记录紧急性和权衡。\\\")\\n+\\n+p(\\\"阶段性医嘱/交接摘要\\\", \\\"Heading 1\\\")\\n+table(\\n+    [\\\"现在\\\", \\\"稳定后\\\", \\\"后续专科\\\"],\\n+    [\\n+        (\\\"当前样本排 DKA/HHS/重叠；评估容量、电解质、肾功能和诱因；严格出入量。结果前诊断仅到“危象待排”。\\\", \\\"分型抗体+C 肽（合适时点）；并发症与甲状腺/生殖代谢分层；高血糖纠正后定量确认是否持续低渗多尿。\\\", \\\"眼科裂隙灯+超声心动图+规范 Ghent 评分/遗传咨询；按指征全主动脉影像；非急诊电离辐射前核实妊娠。\\\"),\\n+    ],\\n+    [5.7, 5.7, 5.7],\\n+)\\n+\\n+p(\\\"禁止事项\\\", \\\"Heading 2\\\")\\n+bullet(\\\"不得用一月余前外院人工转录结果替代本次当前样本。\\\")\\n+bullet(\\\"不得把待查项目写成已完成，不得把“疑似/待排/待分型”改写为确诊。\\\")\\n+bullet(\\\"不得因无恶心、呕吐、腹痛或因患者可交流而排除 DKA/HHS。\\\")\\n+bullet(\\\"不得在危象未排除、渗透性利尿未控制、客观低渗多尿未确认及专科监护未就绪时进行禁水/限水/高渗刺激。\\\")\\n+bullet(\\\"不得以旧末次月经记录代替非急诊电离辐射前的当前妊娠核实。\\\")\\n+\\n+p(\\\"判断标准说明\\\", \\\"Heading 2\\\")\\n+p(\\n+    \\\"DKA/HHS 组成条件依据成人高血糖危象共识框架；多尿路径依据成人多尿—烦渴综合征的标准化评估原则；\\\"\\n+    \\\"马凡综合征按 2010 修订 Ghent 框架。公开资料仅用于解释判断标准，患者事实全部来自本地材料。\\\"\\n+)\\n+\\n+doc.core_properties.title = \\\"内分泌专科入院评估\\\"\\n+doc.core_properties.subject = \\\"高血糖危象、多饮多尿、马凡样表型分阶段评估\\\"\\n+doc.core_properties.author = \\\"内分泌专科评估\\\"\\n+doc.core_properties.keywords = \\\"DKA,HHS,多尿,AVP,马凡综合征,妊娠核实\\\"\\n+doc.save(OUT)\\n+print(OUT)\\n*** End Patch\";\ntext(await tools.apply_patch(patch));\n"
}

